<script setup lang="ts">
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { useSession } from '../../stores/session'
import { request,statuses,date } from '../../api'
import { noteTabShown } from '../../tabNavigation'
const session=useSession(),orders=ref<any[]>([]),notices=ref<any[]>([]),error=ref(false)
onShow(async()=>{if(!session.requireLogin())return;noteTabShown('/pages/home/index');error.value=false;try{if(session.activeRole==='WORKER'){const profile=await request('/workers/me');session.user.workStatus=profile.workStatus}orders.value=(await request('/repair/orders','GET',{size:3})).records;notices.value=(await request('/notices','GET',{size:3})).records}catch{error.value=true}})
function go(path:string){uni.navigateTo({url:path})}
function detail(id:string){go(`/pages/detail/index?id=${id}`)}
</script>
<template><view class="page"><view class="row"><text class="eyebrow">COMMUNITYFIX · 社区服务</text><text class="pill">{{session.activeRole==='WORKER'?'维修人员':'居民'}}</text></view><view class="page-title">你好，{{session.user?.nickname}}</view><view v-if="session.activeRole==='WORKER'&&session.user?.workStatus==='DISABLED'" class="notice">暂未启用接单。请联系申请小区的物业确认维修技能并启用；注册账号可以正常登录。</view><view class="muted">{{session.activeRole==='WORKER'?'把任务接稳，把问题修好。':'今天也为你照顾好家的日常。'}}</view><view class="service-card" @click="session.activeRole==='WORKER'?uni.switchTab({url:'/pages/orders/index'}):go('/pages/create/index')"><view class="service-caption">{{session.activeRole==='WORKER'?'维修任务':'社区报修'}}</view><view class="service-title">{{session.activeRole==='WORKER'?'查看待处理任务':'家里遇到问题了？'}}</view><view class="service-sub">{{session.activeRole==='WORKER'?'接单、处理、提交维修结果':'描述问题，我们帮你安排维修'}}</view><view class="service-button">{{session.activeRole==='WORKER'?'查看任务':'我要报修'}} →</view></view><view class="row quick-links"><view v-if="session.activeRole==='RESIDENT'" @click="go('/pages/bindings/index')"><text>⌂</text><view>房屋绑定</view></view><view @click="uni.switchTab({url:'/pages/messages/index'})"><text>○</text><view>服务消息</view></view><view v-if="session.activeRole==='RESIDENT'" @click="go('/pages/complaints/index')"><text>↗</text><view>投诉进度</view></view><view v-else @click="go('/pages/history/index')"><text>↗</text><view>历史维修</view></view></view><button class="secondary" @click="go('/pages/support/index')">在线客服 · 咨询与转人工</button><view class="row section-title"><text>最近工单</text><text class="link" @click="uni.switchTab({url:'/pages/orders/index'})">全部 →</text></view><view v-if="error" class="error">数据加载失败，可进入工单页重新加载</view><view v-if="!orders.length&&!error" class="empty">还没有报修记录<br>需要维修时，在这里随时提交</view><view v-for="order in orders" :key="order.id" class="card" @click="detail(order.id)"><view class="row"><text class="small">{{order.categoryName}}</text><text class="pill">{{statuses[order.status]}}</text></view><view class="order-title">{{order.title}}</view><view class="row"><text class="muted">{{order.buildingNo}}栋 {{order.roomNo}}室</text><text class="small">{{date(order.createdAt)}}</text></view></view><view v-if="notices.length" class="section-title">社区公告</view><view v-for="notice in notices" :key="notice.id" class="card"><view class="order-title">{{notice.title}}</view><view class="body-text">{{notice.content}}</view></view></view></template>
<style scoped>.service-card{margin-top:34rpx;background:#0b5354;color:white;border-radius:24rpx;padding:36rpx;position:relative;overflow:hidden}.service-caption{font-size:22rpx;color:#b4d5ca;letter-spacing:3rpx}.service-title{font-size:40rpx;font-weight:600;margin:24rpx 0 14rpx}.service-sub{font-size:24rpx;color:#b4d0ca}.service-button{display:inline-block;margin-top:32rpx;border-radius:10rpx;background:#e2f1e8;color:#0b5354;padding:18rpx 30rpx;font-size:26rpx;font-weight:600}.quick-links{padding:36rpx 20rpx;margin:20rpx 0 28rpx}.quick-links>view{text-align:center;font-size:24rpx;color:#658387}.quick-links text{display:block;margin-bottom:14rpx;font-size:34rpx;color:#0b7774}</style>
